from __future__ import annotations

import base64
import gzip
import re
from pathlib import Path

MODULE_PAYLOAD = ''
MARKER = "# RECEIVING_WATER_HISTORY_EXPLORER_V1"
INSERTION = '\n                # RECEIVING_WATER_HISTORY_EXPLORER_V1\n                try:\n                    from receiving_water_history import render_receiving_water_history_explorer\n\n                    render_receiving_water_history_explorer(\n                        high_risk_2025,\n                        company_column=focus_company,\n                        place_column=focus_place,\n                    )\n                except Exception as exc:\n                    st.warning(f"Historical receiving-water evidence explorer could not load: {exc}")\n'

module_path = Path("receiving_water_history.py")
module_bytes = gzip.decompress(base64.b64decode(MODULE_PAYLOAD))
if not module_path.exists() or module_path.read_bytes() != module_bytes:
    module_path.write_bytes(module_bytes)
    print("Wrote receiving_water_history.py")
else:
    print("receiving_water_history.py already current")

app_path = Path("app.py")
text = app_path.read_text(encoding="utf-8")
if MARKER not in text:
    anchor_re = re.compile(
        r'(?P<indent>[ ]*)st\.download_button\(\n'
        r'(?P<body>.*?key="download_priority_2025_links",\n\s*\))',
        flags=re.DOTALL,
    )
    match = anchor_re.search(text)
    if not match:
        raise SystemExit("Could not find the 2025 priority-links download button anchor in app.py")
    insert_at = match.end()
    text = text[:insert_at] + INSERTION + text[insert_at:]
    print("Patched app.py with receiving-water history explorer")
else:
    print("app.py already contains receiving-water history explorer marker")

text = re.sub(
    r'DASHBOARD_RELEASE = "[^"]+"',
    'DASHBOARD_RELEASE = "2026-09-17-receiving-water-history-v28"',
    text,
    count=1,
)
app_path.write_text(text, encoding="utf-8")
